def verify_sudoku(grid, n=4, block_size=2):
    # Check rows
    for i in range(n):
        row = grid[i*n:(i+1)*n]
        if sorted(row) != list(range(1, n+1)):
            return False, f"Row {i} invalid: {row}"

    # Check columns
    for j in range(n):
        col = [grid[i*n+j] for i in range(n)]
        if sorted(col) != list(range(1, n+1)):
            return False, f"Column {j} invalid: {col}"

    # Check blocks
    for bi in range(n // block_size):
        for bj in range(n // block_size):
            block = []
            for i in range(block_size):
                for j in range(block_size):
                    block.append(grid[(bi*block_size+i)*n + (bj*block_size+j)])
            if sorted(block) != list(range(1, n+1)):
                return False, f"Block ({bi},{bj}) invalid: {block}"

    return True, "Valid"

# Proposed solution
solution = [3, 2, 1, 4, 1, 4, 3, 2, 2, 1, 4, 3, 4, 3, 2, 1]

# Check fixed values
print(f"x[7] = {solution[7]} (expected 2)")
print(f"x[9] = {solution[9]} (expected 1)")
print(f"x[12] = {solution[12]} (expected 4)")

# Verify
valid, msg = verify_sudoku(solution)
print(f"Valid: {valid}, {msg}")

# Print grid
print("\nGrid:")
